import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { readArtifact } from "./artifact-inventory.mjs";

const DEFAULT_OUT = fileURLToPath(
  new URL("../frontend/src/views/registry/surface.generated.js", import.meta.url)
);
const HEADER =
  "// Generated by scripts/emit-surface.mjs from data/artifact.json, data/labels.json " +
  "and data/surface.json — do not edit.\n";

function readJson(relative) {
  return JSON.parse(readFileSync(new URL(`../${relative}`, import.meta.url), "utf8"));
}

function controlFor(node) {
  if (node.kind === "root" && node.dimension === "reference") return "selection-picker";
  if (node.kind === "root") return "number";
  if (node.kind === "choice") return "choice-select";
  return "readout";
}

function nodeEntry(node) {
  const reference = node.kind === "root" && node.dimension === "reference";
  return {
    kind: reference ? "reference" : node.kind,
    isInput: node.kind === "root" || node.kind === "choice",
    control: controlFor(node),
    dimension: reference ? "reference" : (node.output?.dimension ?? node.dimension ?? null),
    taxonomy: node.output?.taxonomy ?? node.taxonomy ?? null,
  };
}

function pathEntry(spec, extra = {}) {
  return {
    kind: "path",
    isInput: false,
    control: "readout",
    dimension: spec.dimension ?? null,
    taxonomy: spec.taxonomy ?? null,
    ...extra,
  };
}

function rootFailures(artifact, surface) {
  const roots = Object.entries(artifact.nodes)
    .filter(([, node]) => node.kind === "root" || node.kind === "choice")
    .map(([id]) => id);
  const declared = new Set([
    ...Object.keys(surface.roots?.inherited ?? {}),
    ...Object.keys(surface.roots?.authored ?? {}),
  ]);
  const failures = roots
    .filter((id) => !declared.has(id))
    .map((id) => `undeclared root "${id}"`);
  for (const id of declared) {
    if (!roots.includes(id)) failures.push(`"${id}" is not a root or choice`);
  }
  return failures;
}

function labelFailures(artifact, labels, surface) {
  const bases = (surface.families ?? []).map((family) => family.base);
  const failures = [];
  for (const id of Object.keys(artifact.nodes)) {
    const inFamily = bases.some((base) => id.startsWith(`${base}.`));
    if (labels[id] || surface.card_labelled?.[id] || inFamily) continue;
    failures.push(`unlabelled node "${id}"`);
  }
  return failures;
}

function coverageFailures(artifact, labels, surface) {
  return [...rootFailures(artifact, surface), ...labelFailures(artifact, labels, surface)];
}

function addOutputs(paths, id, node) {
  if (node.kind !== "boundary") return;
  for (const [key, spec] of Object.entries(node.outputs ?? {})) {
    paths[`${id}.${key}`] = pathEntry(spec, { owner: id });
  }
}

function addSelectionFields(paths, id, node, artifact) {
  if (node.kind !== "selection") return;
  const schema = artifact.primitive_schemas[node.output?.schema] ?? {};
  for (const [field, spec] of Object.entries(schema)) {
    paths[`${id}.${field}`] = pathEntry(spec, { owner: id, selectionRef: node.ref });
  }
}

function addIdentity(paths, artifact) {
  for (const [namespace, schemaId] of Object.entries(artifact.identity ?? {})) {
    for (const [field, spec] of Object.entries(artifact.primitive_schemas[schemaId] ?? {})) {
      paths[`${namespace}.${field}`] = pathEntry(spec, { identityNamespace: namespace });
    }
  }
}

function buildManifest(artifact, labels, surface) {
  const failures = coverageFailures(artifact, labels, surface);
  if (failures.length > 0) {
    throw new Error(`surface declarations are incomplete:\n  ${failures.join("\n  ")}`);
  }

  const paths = {};
  for (const [id, node] of Object.entries(artifact.nodes)) {
    paths[id] = { ...nodeEntry(node), owner: id };
    addOutputs(paths, id, node);
    addSelectionFields(paths, id, node, artifact);
  }
  addIdentity(paths, artifact);

  const sorted = Object.fromEntries(
    Object.entries(paths).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
  );

  return {
    schema_version: artifact.schema_version,
    paths: sorted,
    roots: surface.roots,
    families: surface.families,
    card_labelled: surface.card_labelled,
  };
}

function writeIfChanged(path, text) {
  try {
    if (readFileSync(path, "utf8") === text) return false;
  } catch {
    // The output may not exist yet.
  }
  writeFileSync(path, text);
  return true;
}

function render(manifest) {
  const paths = Object.entries(manifest.paths)
    .map(([id, entry]) => `  ${JSON.stringify(id)}: ${JSON.stringify(entry)},`)
    .join("\n");
  return (
    HEADER +
    "export const surfaceManifest = {\n" +
    `  "schema_version": ${manifest.schema_version},\n` +
    `  "paths": {\n${paths}\n  },\n` +
    `  "roots": ${JSON.stringify(manifest.roots)},\n` +
    `  "families": ${JSON.stringify(manifest.families)},\n` +
    `  "card_labelled": ${JSON.stringify(manifest.card_labelled)}\n` +
    "};\n"
  );
}

function main() {
  const artifact = readArtifact();
  const labels = readJson("data/labels.json");
  const surface = readJson("data/surface.json");
  const manifest = buildManifest(artifact, labels, surface);
  const text = render(manifest);

  const outIndex = process.argv.indexOf("--out");
  const out = outIndex === -1 ? DEFAULT_OUT : process.argv[outIndex + 1];
  const changed = writeIfChanged(out, text);
  console.log(
    `surface manifest: ${changed ? "wrote" : "unchanged"} ${out} ` +
      `(${Object.keys(manifest.paths).length} paths, ${manifest.families.length} families)`
  );
}

main();
